1	import { expect } from "chai";
2	import { network } from "hardhat";
3	
4	const { ethers, networkHelpers } = await network.create();
5	const INITIAL_SUPPLY = 10_000n;
6	
7	async function deployToken() {
8	  const [issuer, investorB, investorC, unapprovedD, unauthorisedE, otherIssuer, deployer] = await ethers.getSigners();
9	  const token = await ethers.deployContract("AssetToken", ["Campus Property Token", "CPT", INITIAL_SUPPLY, issuer.address]);
10	  await token.waitForDeployment();
11	  return { token, issuer, investorB, investorC, unapprovedD, unauthorisedE, otherIssuer, deployer };
12	}
13	
14	async function approvedHolders() {
15	  const state = await deployToken();
16	  await state.token.setWhitelisted(state.investorB.address, true);
17	  await state.token.setWhitelisted(state.investorC.address, true);
18	  await state.token.transfer(state.investorB.address, 100n);
19	  return state;
20	}
21	
22	describe("AssetToken — Phase 2", function () {
23	  describe("A — deployment and fixed supply", function () {
24	    it("sets the name, symbol, and whole-unit decimals", async function () {
25	      const { token } = await networkHelpers.loadFixture(deployToken);
26	      expect(await token.name()).to.equal("Campus Property Token");
27	      expect(await token.symbol()).to.equal("CPT");
28	      expect(await token.decimals()).to.equal(0n);
29	    });
30	
31	    it("mints exactly 10,000 whole units to the designated issuer", async function () {
32	      const { token, issuer, investorB } = await networkHelpers.loadFixture(deployToken);
33	      expect(await token.totalSupply()).to.equal(INITIAL_SUPPLY);
34	      expect(await token.balanceOf(issuer.address)).to.equal(INITIAL_SUPPLY);
35	      expect(await token.balanceOf(investorB.address)).to.equal(0n);
36	      expect(await token.issuer()).to.equal(issuer.address);
37	    });
38	
39	    it("emits the standard mint Transfer from the zero address", async function () {
40	      const { token, issuer } = await networkHelpers.loadFixture(deployToken);
41	      await expect(token.deploymentTransaction()).to.emit(token, "Transfer")
42	        .withArgs(ethers.ZeroAddress, issuer.address, INITIAL_SUPPLY);
43	    });
44	
45	    it("whitelists the issuer and leaves other addresses, including zero, ineligible", async function () {
46	      const { token, issuer, investorB } = await networkHelpers.loadFixture(deployToken);
47	      expect(await token.isWhitelisted(issuer.address)).to.equal(true);
48	      expect(await token.isWhitelisted(investorB.address)).to.equal(false);
49	      expect(await token.isWhitelisted(ethers.ZeroAddress)).to.equal(false);
50	      expect(await token.whitelist(issuer.address)).to.equal(true);
51	    });
52	
53	    it("grants the issuer the administrator and compliance roles", async function () {
54	      const { token, issuer, unauthorisedE } = await networkHelpers.loadFixture(deployToken);
55	      const role = await token.COMPLIANCE_ROLE();
56	      expect(role).to.equal(ethers.id("COMPLIANCE_ROLE"));
57	      expect(await token.hasRole(await token.DEFAULT_ADMIN_ROLE(), issuer.address)).to.equal(true);
58	      expect(await token.hasRole(role, issuer.address)).to.equal(true);
59	      expect(await token.hasRole(role, unauthorisedE.address)).to.equal(false);
60	      expect(await token.getRoleAdmin(role)).to.equal(await token.DEFAULT_ADMIN_ROLE());
61	    });
62	
63	    it("rejects a zero issuer", async function () {
64	      const { token } = await networkHelpers.loadFixture(deployToken);
65	      await expect(ethers.deployContract("AssetToken", ["Invalid", "BAD", 1n, ethers.ZeroAddress]))
66	        .to.be.revertedWithCustomError(token, "InvalidIssuer");
67	    });
68	
69	    it("rejects a zero supply", async function () {
70	      const { token, issuer } = await networkHelpers.loadFixture(deployToken);
71	      await expect(ethers.deployContract("AssetToken", ["Invalid", "BAD", 0n, issuer.address]))
72	        .to.be.revertedWithCustomError(token, "InvalidInitialSupply");
73	    });
74	
75	    it("exposes no mint or burn entry point, even to the administrator", async function () {
76	      const { token, issuer, investorB } = await networkHelpers.loadFixture(deployToken);
77	      const publicInterface = new ethers.Interface(token.interface.fragments);
78	      for (const signature of ["mint(address,uint256)", "_mint(address,uint256)", "burn(uint256)", "burnFrom(address,uint256)"]) {
79	        expect(publicInterface.getFunction(signature)).to.equal(null);
80	      }
81	      const mintInterface = new ethers.Interface(["function mint(address,uint256)"]);
82	      await expect(issuer.sendTransaction({
83	        to: await token.getAddress(),
84	        data: mintInterface.encodeFunctionData("mint", [investorB.address, 1n]),
85	      })).to.revert(ethers);
86	      expect(await token.totalSupply()).to.equal(INITIAL_SUPPLY);
87	      expect(await token.balanceOf(investorB.address)).to.equal(0n);
88	    });
89	
90	    it("assigns supply and roles to the issuer instead of a different deploying account", async function () {
91	      const { issuer, deployer } = await networkHelpers.loadFixture(deployToken);
92	      const token = await ethers.deployContract("AssetToken", ["Other", "OTH", 25n, issuer.address], deployer);
93	      expect(await token.balanceOf(issuer.address)).to.equal(25n);
94	      expect(await token.balanceOf(deployer.address)).to.equal(0n);
95	      for (const role of [await token.DEFAULT_ADMIN_ROLE(), await token.COMPLIANCE_ROLE()]) {
96	        expect(await token.hasRole(role, issuer.address)).to.equal(true);
97	        expect(await token.hasRole(role, deployer.address)).to.equal(false);
98	      }
99	      expect(await token.isWhitelisted(deployer.address)).to.equal(false);
100	    });
101	
102	    it("supports construction by a contract without granting that contract authority", async function () {
103	      const { issuer, investorB, deployer } = await networkHelpers.loadFixture(deployToken);
104	      const harness = await ethers.deployContract("AssetTokenDeploymentHarness", [issuer.address], deployer);
105	      const token = await ethers.getContractAt("AssetToken", await harness.token(), issuer);
106	      expect(await token.balanceOf(issuer.address)).to.equal(INITIAL_SUPPLY);
107	      for (const role of [await token.DEFAULT_ADMIN_ROLE(), await token.COMPLIANCE_ROLE()]) {
108	        expect(await token.hasRole(role, issuer.address)).to.equal(true);
109	        expect(await token.hasRole(role, await harness.getAddress())).to.equal(false);
110	      }
111	      expect(await token.isWhitelisted(await harness.getAddress())).to.equal(false);
112	      await token.setWhitelisted(investorB.address, true);
113	      await token.transfer(investorB.address, 1n);
114	      expect(await token.balanceOf(investorB.address)).to.equal(1n);
115	    });
116	  });
117	
118	  describe("B — whitelist and role administration", function () {
119	    it("approves investors B and C with publicly readable status", async function () {
120	      const { token, investorB, investorC } = await networkHelpers.loadFixture(deployToken);
121	      await token.setWhitelisted(investorB.address, true);
122	      await token.setWhitelisted(investorC.address, true);
123	      expect(await token.isWhitelisted(investorB.address)).to.equal(true);
124	      expect(await token.isWhitelisted(investorC.address)).to.equal(true);
125	      expect(await token.whitelist(investorB.address)).to.equal(true);
126	    });
127	
128	    it("emits investor, status, and operator on approval and revocation", async function () {
129	      const { token, issuer, investorB } = await networkHelpers.loadFixture(deployToken);
130	      await expect(token.setWhitelisted(investorB.address, true))
131	        .to.emit(token, "WhitelistUpdated").withArgs(investorB.address, true, issuer.address);
132	      await expect(token.setWhitelisted(investorB.address, false))
133	        .to.emit(token, "WhitelistUpdated").withArgs(investorB.address, false, issuer.address);
134	      expect(await token.isWhitelisted(investorB.address)).to.equal(false);
135	      expect(await token.whitelist(investorB.address)).to.equal(false);
136	    });
137	
138	    for (const approved of [true, false]) {
139	      it(`rejects unauthorised whitelist update approved=${approved}`, async function () {
140	        const { token, investorB, unauthorisedE } = await networkHelpers.loadFixture(
141	          approved ? deployToken : approvedHolders,
142	        );
143	        await expect(token.connect(unauthorisedE).setWhitelisted(investorB.address, approved))
144	          .to.be.revertedWithCustomError(token, "AccessControlUnauthorizedAccount")
145	          .withArgs(unauthorisedE.address, await token.COMPLIANCE_ROLE());
146	        expect(await token.isWhitelisted(investorB.address)).to.equal(!approved);
147	      });
148	
149	      it(`rejects a zero investor when approved=${approved}`, async function () {
150	        const { token } = await networkHelpers.loadFixture(deployToken);
151	        await expect(token.setWhitelisted(ethers.ZeroAddress, approved))
152	          .to.be.revertedWithCustomError(token, "InvalidInvestor");
153	      });
154	    }
155	
156	    it("treats repeated status updates as no-ops without duplicate events", async function () {
157	      const { token, investorB } = await networkHelpers.loadFixture(deployToken);
158	      await expect(token.setWhitelisted(investorB.address, false)).not.to.emit(token, "WhitelistUpdated");
159	      await token.setWhitelisted(investorB.address, true);
160	      await expect(token.setWhitelisted(investorB.address, true)).not.to.emit(token, "WhitelistUpdated");
161	      expect(await token.isWhitelisted(investorB.address)).to.equal(true);
162	      await token.setWhitelisted(investorB.address, false);
163	      await expect(token.setWhitelisted(investorB.address, false)).not.to.emit(token, "WhitelistUpdated");
164	      expect(await token.isWhitelisted(investorB.address)).to.equal(false);
165	    });
166	
167	    it("revokes a funded investor without confiscation, burning, or Transfer events", async function () {
168	      const { token, issuer, investorB } = await networkHelpers.loadFixture(approvedHolders);
169	      await expect(token.setWhitelisted(investorB.address, false)).not.to.emit(token, "Transfer");
170	      expect(await token.isWhitelisted(investorB.address)).to.equal(false);
171	      expect(await token.balanceOf(investorB.address)).to.equal(100n);
172	      expect(await token.balanceOf(issuer.address)).to.equal(9_900n);
173	      expect(await token.totalSupply()).to.equal(INITIAL_SUPPLY);
174	    });
175	
176	    it("delegates compliance and records the actual delegate as operator", async function () {
177	      const { token, investorB, unauthorisedE } = await networkHelpers.loadFixture(deployToken);
178	      await token.grantRole(await token.COMPLIANCE_ROLE(), unauthorisedE.address);
179	      await expect(token.connect(unauthorisedE).setWhitelisted(investorB.address, true))
180	        .to.emit(token, "WhitelistUpdated").withArgs(investorB.address, true, unauthorisedE.address);
181	      expect(await token.isWhitelisted(unauthorisedE.address)).to.equal(false);
182	      expect(await token.hasRole(await token.DEFAULT_ADMIN_ROLE(), unauthorisedE.address)).to.equal(false);
183	    });
184	
185	    it("prevents unauthorised accounts from granting themselves compliance authority", async function () {
186	      const { token, unauthorisedE } = await networkHelpers.loadFixture(deployToken);
187	      await expect(token.connect(unauthorisedE).grantRole(await token.COMPLIANCE_ROLE(), unauthorisedE.address))
188	        .to.be.revertedWithCustomError(token, "AccessControlUnauthorizedAccount")
189	        .withArgs(unauthorisedE.address, await token.DEFAULT_ADMIN_ROLE());
190	    });
191	
192	    it("prevents compliance-only delegates from granting roles", async function () {
193	      const { token, investorB, unauthorisedE } = await networkHelpers.loadFixture(deployToken);
194	      await token.grantRole(await token.COMPLIANCE_ROLE(), unauthorisedE.address);
195	      await expect(token.connect(unauthorisedE).grantRole(await token.COMPLIANCE_ROLE(), investorB.address))
196	        .to.be.revertedWithCustomError(token, "AccessControlUnauthorizedAccount")
197	        .withArgs(unauthorisedE.address, await token.DEFAULT_ADMIN_ROLE());
198	    });
199	
200	    it("removes compliance authority immediately when the role is revoked", async function () {
201	      const { token, investorB, unauthorisedE } = await networkHelpers.loadFixture(deployToken);
202	      const role = await token.COMPLIANCE_ROLE();
203	      await token.grantRole(role, unauthorisedE.address);
204	      await token.revokeRole(role, unauthorisedE.address);
205	      await expect(token.connect(unauthorisedE).setWhitelisted(investorB.address, true))
206	        .to.be.revertedWithCustomError(token, "AccessControlUnauthorizedAccount").withArgs(unauthorisedE.address, role);
207	    });
208	
209	    it("requires compliance authority even for an administrator whose compliance role was revoked", async function () {
210	      const { token, issuer, investorB } = await networkHelpers.loadFixture(deployToken);
211	      const role = await token.COMPLIANCE_ROLE();
212	      await token.revokeRole(role, issuer.address);
213	      await expect(token.setWhitelisted(investorB.address, true))
214	        .to.be.revertedWithCustomError(token, "AccessControlUnauthorizedAccount").withArgs(issuer.address, role);
215	      await token.grantRole(role, issuer.address);
216	      await token.setWhitelisted(investorB.address, true);
217	      expect(await token.isWhitelisted(investorB.address)).to.equal(true);
218	    });
219	  });
220	
221	  describe("C — direct transfers and revocation", function () {
222	    it("transfers 100 units to B and emits the standard Transfer event", async function () {
223	      const { token, issuer, investorB } = await networkHelpers.loadFixture(deployToken);
224	      await token.setWhitelisted(investorB.address, true);
225	      await expect(token.transfer(investorB.address, 100n))
226	        .to.emit(token, "Transfer").withArgs(issuer.address, investorB.address, 100n);
227	      expect(await token.balanceOf(issuer.address)).to.equal(9_900n);
228	      expect(await token.balanceOf(investorB.address)).to.equal(100n);
229	    });
