1	// Deploys the AssetFactory (spec-v1 §4; Phase 3 §3.1) with the first signer as platform admin.
2	// Usage: npm run deploy:local (persistent node); npm run deploy:ephemeral (throwaway)
3	//        npx hardhat run scripts/deploy.ts --network sepolia
4	// On persistent (HTTP) networks the address is written to frontend/src/config/addresses.json (spec-v1 §7).
5	
6	import { network } from "hardhat";
7	import fs from "node:fs";
8	import path from "node:path";
9	
10	const { ethers, networkName, networkConfig } = await network.getOrCreate();
11	const [admin] = await ethers.getSigners();
12	const { chainId } = await ethers.provider.getNetwork();
13	
14	console.log(`Network: ${networkName} (chain ${chainId})`);
15	console.log(`Admin:   ${admin.address}`);
16	
17	const factory = await ethers.deployContract("AssetFactory", [admin.address]);
18	await factory.waitForDeployment();
19	const factoryAddress = await factory.getAddress();
20	const deployBlock = (await factory.deploymentTransaction()?.wait())?.blockNumber ?? null;
21	console.log(`AssetFactory deployed to: ${factoryAddress}`);
22	
23	if (networkConfig.type === "http") {
24	  const file = path.join("frontend", "src", "config", "addresses.json");
25	  const addresses = {
26	    note: "Populated by scripts/deploy.ts after deployment. Do not edit by hand.",
27	    network: networkName,
28	    chainId: Number(chainId),
29	    AssetFactory: factoryAddress,
30	    admin: admin.address,
31	    deployBlock: deployBlock ?? 0,
32	    deployBlockHash: deployBlock === null ? undefined : (await ethers.provider.getBlock(deployBlock))?.hash,
33	    runtimeCodeHash: ethers.keccak256(await ethers.provider.getCode(factoryAddress)),
34	  };
35	  fs.writeFileSync(file, JSON.stringify(addresses, null, 2) + "\n");
36	  console.log(`Wrote ${file}`);
37	  await import("./syncFrontend.mjs");
38	} else {
39	  console.log("In-process network: addresses.json not updated (the deployment ends with this script).");
40	}
