2	import { abis } from "../config/contracts";
3	const interfaces = Object.values(abis).map((abi) => new Interface(abi));
4	const messages: Record<string, string> = {
5	  NotAdmin: "Only the platform administrator can manage issuers.",
6	  NotIssuer: "Only this asset’s issuer can manage its offering.",
7	  IssuerNotAuthorised: "This wallet is not authorised to create assets.",
8	  IssuerAlreadyAuthorised: "This issuer is already authorised.",
9	  AdminCannotBeIssuer: "The platform administrator cannot be an issuer.",
10	  AccessControlUnauthorizedAccount:
11	    "This wallet does not hold the required token role.",
12	  InvestorNotWhitelisted: "Your wallet is not approved for this asset.",
13	  SenderNotWhitelisted:
14	    "The sender is not whitelisted. The issuer must restore its eligibility.",
15	  RecipientNotWhitelisted:
16	    "The recipient is not whitelisted. The issuer must approve it first.",
17	  InsufficientInventory: "The offering has insufficient token inventory.",
18	  ERC20InsufficientBalance: "Insufficient token balance.",
19	  ERC20InsufficientAllowance:
20	    "Approve sufficient token spending before depositing.",
21	  SaleIsClosed: "This offering is permanently closed.",
22	  SaleNotClosed: "Close the offering before recovering unsold tokens.",
23	  IncorrectPayment: "Incorrect ETH payment. Refresh the asset and try again.",
24	  NoProceeds: "There are no proceeds to withdraw.",
25	  NoUnsoldTokens: "There are no unsold tokens to recover.",
26	  NoExcessETH: "There is no excess ETH to recover.",
27	  AssetNotFound: "This asset does not exist in the registry.",
28	};
29	export function rejected(error: any) {
30	  return (
31	    error?.code === 4001 ||
32	    isError(error, "ACTION_REJECTED") ||
33	    error?.info?.error?.code === 4001
34	  );
35	}
36	export function errorMessage(error: any): string {
37	  if (rejected(error))
38	    return "Request rejected in your wallet. No transaction was confirmed.";
39	  if (isError(error, "INSUFFICIENT_FUNDS"))
40	    return "Insufficient ETH for this payment and network fees.";
41	  if (error?.code === -32002)
42	    return "A wallet request is already open. Check your wallet.";
43	  const data = error?.data ?? error?.info?.error?.data;
44	  for (const iface of interfaces) {
45	    try {
46	      const parsed = iface.parseError(
47	        typeof data === "string" ? data : data?.data,
48	      );
49	      if (parsed)
50	        return (
51	          messages[parsed.name] ||
52	          `Contract rejected the request: ${parsed.name}.`
53	        );
54	    } catch {
55	      /* Try the next compiled ABI. */
56	    }
57	  }
58	  if (
59	    ["NETWORK_ERROR", "SERVER_ERROR", "TIMEOUT", "UNKNOWN_ERROR"].includes(
60	      error?.code,
61	    ) ||
62	    /fetch|ECONNREFUSED/i.test(error?.message || "")
63	  )
64	    return "RPC connection unavailable or request failed. Check the local node, network and deployment, then retry.";
65	  return (
66	    error?.shortMessage || error?.message || "The request failed. Please retry."
67	  );
68	}
