# Checks the CLAUDE.md issue workflow for every AUD issue that has test(...)/fix(...) commits.
$issues = '005','006','007','008','009','010','011','012','013','014'
foreach ($n in $issues) {
  $id = "AUD-$n"
  $test = @(git log main --format=%h --grep "^test($id)" --fixed-strings)
  $fix = @(git log main --format=%h --grep "^fix($id)" --fixed-strings)
  # --fixed-strings with ^ does not anchor; filter by subject prefix instead
  $test = @(git log main --format='%h %s' | Where-Object { $_ -match "^\w+ test\($id\)" } | % { ($_ -split ' ')[0] })
  $fix = @(git log main --format='%h %s' | Where-Object { $_ -match "^\w+ fix\($id\)" } | % { ($_ -split ' ')[0] })
  $file = Get-ChildItem docs/issues -Filter "$id-*.md" | Select-Object -First 1
  $text = [IO.File]::ReadAllText($file.FullName)
  $placeholders = [regex]::Matches($text, 'FIX_COMMIT|BEFORE_RUN|AFTER_RUN|AFTER_COUNT|SIZES|critical / high|unit test / fuzz') | % { $_.Value }
  $status = ([regex]::Match($text, '\| Status \| ([^|]+)\|')).Groups[1].Value.Trim()
  $cited = [regex]::Matches($text, '\b[0-9a-f]{7}\b') | % { $_.Value } | Sort-Object -Unique
  $missing = $cited | Where-Object { -not (git cat-file -e "$_^{commit}" 2>$null; $LASTEXITCODE -eq 0) }
  $line = "$id status='$status' test=$($test -join ',') fix=$($fix -join ',')"
  if ($test.Count -eq 1 -and $fix.Count -eq 1) {
    git merge-base --is-ancestor $test[0] $fix[0]; $order = ($LASTEXITCODE -eq 0)
    $testFiles = git show --name-only --format= $test[0] | Where-Object { $_ }
    $prodInTest = $testFiles | Where-Object { $_ -match '^(contracts|frontend/src|scripts|hardhat\.config|package\.json)' -and $_ -notmatch '^frontend/src/test/' }
    $fixFiles = git show --name-only --format= $fix[0] | Where-Object { $_ }
    $testsInFix = $fixFiles | Where-Object { $_ -match '^test/|/test/|\.test\.ts$' }
    $runs = Get-ChildItem docs/evidence/runs -Directory | Where-Object { $_.Name -like "*_${id}-before" -or $_.Name -like "*_${id}-after" }
    $ev = foreach ($r in $runs) { $t = Get-Content "$($r.FullName)/test.log" -Raw; $f = [regex]::Match($t, '(\d+) failing').Groups[1].Value; "$(($r.Name -split '_')[-1])=fail:$(if ($f) { $f } else { 0 })" }
    $line += " order_ok=$order prod_files_in_test_commit=[$($prodInTest -join ',')] tests_in_fix_commit=[$($testsInFix -join ',')] runs=[$($ev -join ' ')]"
  }
  $line += " placeholders=[$($placeholders -join ',')] missing_cited_commits=[$($missing -join ',')]"
  $line
}

