// Docs consistency checks for the files this session edited. Run from the repo root.
import fs from "node:fs";
import path from "node:path";
import { execFileSync } from "node:child_process";

const git = (...a) => execFileSync("git", a, { encoding: "utf8" });
const read = (f) => fs.readFileSync(f, "utf8");
const edited = git("diff", "--name-only", "0febe23", "HEAD", "--", "*.md")
  .split("\n").filter((f) => f && !f.startsWith("docs/ai-logs/raw/") && !f.startsWith("docs/ai-logs/exports/") && fs.existsSync(f));

// 1. Relative markdown links resolve (file part; #anchors checked for README only).
const broken = [];
for (const f of edited) {
  for (const m of read(f).matchAll(/\]\(([^)\s]+)\)/g)) {
    const target = m[1];
    if (/^(https?:|mailto:)/.test(target)) continue;
    const [file, anchor] = target.split("#");
    if (!file) {
      if (f === "README.md" && anchor) {
        const slugs = [...read(f).matchAll(/^#+\s+(.+)$/gm)].map((h) => h[1].toLowerCase().replace(/[^a-z0-9 -]/g, "").trim().replace(/\s+/g, "-"));
        if (!slugs.includes(anchor)) broken.push(`${f} -> #${anchor}`);
      }
      continue;
    }
    if (!fs.existsSync(path.join(path.dirname(f), decodeURIComponent(file)))) broken.push(`${f} -> ${target}`);
  }
}
console.log(`links: ${edited.length} edited .md files, broken: ${broken.length ? broken.join("; ") : "none"}`);

// 2. Issue INDEX status agrees with each issue file's Status field (fixed vs not).
const index = read("docs/issues/INDEX.md");
const mismatch = [];
for (const row of index.matchAll(/^\| \[(AUD-\d{3})\]\(([^)]+)\) \|.*\| ([^|]*) \|\s*$/gm)) {
  const [, id, file, indexStatus] = row;
  const fileStatus = (read(path.join("docs/issues", file)).match(/\| Status \| ([^|]+)\|/) || [])[1]?.trim() ?? "?";
  const a = /^fixed/.test(indexStatus.trim()), b = /^fixed/.test(fileStatus);
  if (a !== b) mismatch.push(`${id}: index "${indexStatus.trim()}" vs file "${fileStatus}"`);
}
console.log(`issue INDEX vs files: ${mismatch.length ? mismatch.join("; ") : "consistent"}`);

// 3. CLAUDE.md: no lines removed since session start; every added rule cites an AUD issue.
const diff = git("diff", "0febe23", "HEAD", "--", "CLAUDE.md").split("\n");
const removed = diff.filter((l) => l.startsWith("-") && !l.startsWith("---"));
const added = diff.filter((l) => l.startsWith("+- "));
const uncited = added.filter((l) => !/^\+- AUD-\d{3}/.test(l));
console.log(`CLAUDE.md: lines removed ${removed.length}, rules added ${added.length} (${added.map((l) => l.slice(3, 10)).join(", ")}), uncited ${uncited.length}`);

// 4. ai-logs INDEX table is contiguous (no blank line between the header and the last row).
const lines = read("docs/ai-logs/INDEX.md").split(/\r?\n/);
const first = lines.findIndex((l) => l.startsWith("| Date")), last = lines.map((l) => l.startsWith("|")).lastIndexOf(true);
const gaps = lines.slice(first, last + 1).filter((l) => !l.startsWith("|")).length;
console.log(`ai-logs INDEX: ${last - first - 1} rows, non-table lines inside table: ${gaps}`);

// 5. spec-v1 frozen; decision IDs referenced in docs exist in phase3-requirements.
const spec = read("docs/spec/spec-v1.md");
const decisions = read("docs/spec/phase3-requirements.md");
const defined = new Set([...decisions.matchAll(/^\| (D\d+) \|/gm)].map((m) => m[1]).concat(decisions.includes("## D5 decision") ? ["D5"] : [], decisions.includes("## D10 decision") ? ["D10"] : []));
console.log(`spec-v1 TODO(decision) markers: ${(spec.match(/TODO\(decision\)/g) || []).length - 1} (excluding the "none remain" sentence); decisions defined: ${[...defined].sort((a, b) => a.slice(1) - b.slice(1)).join(",")}`);

