// Map each Phase 5 Task 5.3 edge case to existing test titles (contract and frontend suites).
import fs from "node:fs";
import path from "node:path";

const dirs = ["test", "frontend/src/test", "frontend/integration"];
const titles = [];
for (const d of dirs) {
  for (const f of fs.readdirSync(d).filter((f) => /\.test\.tsx?$/.test(f))) {
    const t = fs.readFileSync(path.join(d, f), "utf8");
    for (const m of t.matchAll(/\bit\(\s*(["'`])((?:(?!\1).)+)\1/g)) titles.push(`${d}/${f} :: ${m[2]}`);
  }
}
const cases = {
  "Wrong network": /wrong network|network mismatch|mismatch|chain/i,
  "Wallet refuses a transaction": /reject|refus|4001|denied/i,
  "Buyer has insufficient ETH": /insufficient (eth|funds)|INSUFFICIENT_FUNDS|not enough eth|fees/i,
  "Sale inventory is exhausted": /inventory|more than (the )?inventory|exhaust|sold out/i,
  "Purchase amount is zero": /zero|quantity == 0|0 tokens|quantity is 0/i,
  "Recipient is not whitelisted": /recipient|not whitelisted|unapproved|ineligible/i,
  "Compliance admin revokes before a transfer": /revok/i,
  "Attacker uses another issuer's admin functions": /another issuer|other issuer|non-issuer|unauthori[sz]ed|isolat/i,
  "Withdraw proceeds with none remaining": /no proceeds|NoProceeds|nothing to withdraw|zero proceeds|withdraw.*(twice|again|none)/i,
  "ETH withdrawal to a contract that rejects payment": /reject(s|ing)? (eth|payment)|refus|cannot receive|revert.*receive|rejecting/i,
};
for (const [name, re] of Object.entries(cases)) {
  const hits = titles.filter((t) => re.test(t.split(" :: ")[1]));
  console.log(`\n## ${name} (${hits.length})`);
  for (const h of hits.slice(0, 6)) console.log(`  ${h.slice(0, 170)}`);
  if (hits.length > 6) console.log(`  … ${hits.length - 6} more`);
}
console.log(`\n(total titles scanned: ${titles.length})`);

